$KulaShop_options[9] = {
	npc = 1 & $npc_id = 'Kulaside'
	$sp_text[9] = '[쿨라]<br>&nbsp;개인실 인테리어를 새로 꾸며 드려요. 방마다 따로 꾸미고, 스탠다드 $1000, 퀄리티 $2500, 럭셔리 $5000이에요. 어느 방을 꾸밀까요?</div>'
